export type ParsedPayInstruction<
  TProgram extends string = typeof BOND_LIFECYCLE_PROGRAM_ADDRESS,
  TAccountMetas extends readonly AccountMeta[] = readonly AccountMeta[],
> = {
  programAddress: Address<TProgram>;
  accounts: {
    payer: TAccountMetas[0];
    mint: TAccountMetas[1];
    bond: TAccountMetas[2];
    event: TAccountMetas[3];
    tokenAccount: TAccountMetas[4];
    snapshot: TAccountMetas[5];
    paymentMint: TAccountMetas[6];
    vault: TAccountMetas[7];
    destination: TAccountMetas[8];
    tokenProgram: TAccountMetas[9];
  };
  data: PayInstructionData;
};

export function parsePayInstruction<
  TProgram extends string,
  TAccountMetas extends readonly AccountMeta[],
>(
  instruction: Instruction<TProgram> &
    InstructionWithAccounts<TAccountMetas> &
    InstructionWithData<ReadonlyUint8Array>,
): ParsedPayInstruction<TProgram, TAccountMetas> {
  if (instruction.accounts.length < 10) {
    throw new SolanaError(
      SOLANA_ERROR__PROGRAM_CLIENTS__INSUFFICIENT_ACCOUNT_METAS,
      {
        actualAccountMetas: instruction.accounts.length,
        expectedAccountMetas: 10,
      },
    );
  }
  let accountIndex = 0;
  const getNextAccount = () => {
    const accountMeta = (instruction.accounts as TAccountMetas)[accountIndex]!;
    accountIndex += 1;
    return accountMeta;
  };
  return {
    programAddress: instruction.programAddress,
    accounts: {
      payer: getNextAccount(),
      mint: getNextAccount(),
      bond: getNextAccount(),
      event: getNextAccount(),
      tokenAccount: getNextAccount(),
      snapshot: getNextAccount(),
      paymentMint: getNextAccount(),
      vault: getNextAccount(),
      destination: getNextAccount(),
      tokenProgram: getNextAccount(),
    },
    data: getPayInstructionDataDecoder().decode(instruction.data),
  };
}
